import random

class Node:
    __slots__ = ('val', 'pri', 'size', 'l', 'r')
    def __init__(self, v):
        self.val = v; self.pri = random.random()
        self.size = 1; self.l = self.r = None

def sz(n): return n.size if n else 0
def upd(n):
    if n: n.size = 1 + sz(n.l) + sz(n.r)
def merge(a, b):
    if not a or not b: return a or b
    if a.pri > b.pri:
        a.r = merge(a.r, b); upd(a); return a
    b.l = merge(a, b.l); upd(b); return b
def split(t, k):
    if not t: return None, None
    if sz(t.l) < k:
        a, b = split(t.r, k - sz(t.l) - 1)
        t.r = a; upd(t); return t, b
    a, b = split(t.l, k)
    t.l = b; upd(t); return a, t

def build(vals={{values}}):
    root = None
    for v in vals: root = merge(root, Node(v))
    return root
